-- Directory (one Durable Object): baseline equal to D1 migrations 0001–0009, generated by tools/db/split-baseline.mjs. Forward-only
-- and expand-only from here (docs/multi-user.md 5.7): add tables, columns and indexes; never drop or rename what
-- the previous release still reads.

CREATE TABLE budget (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE user (
  id TEXT PRIMARY KEY,
  github_login TEXT,
  email TEXT NOT NULL UNIQUE,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE budget_member (
  budget_id TEXT NOT NULL REFERENCES budget(id),
  user_id TEXT NOT NULL REFERENCES user(id),
  role TEXT NOT NULL DEFAULT 'owner' CHECK (role IN ('owner', 'member')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  PRIMARY KEY (budget_id, user_id)
);
CREATE TABLE usage_day (
  day TEXT PRIMARY KEY,
  rows_read INTEGER NOT NULL,        -- from GraphQL Analytics as of refreshed_at
  rows_written INTEGER NOT NULL,
  est_read INTEGER NOT NULL DEFAULT 0,     -- this app's own counts since the last refresh
  est_written INTEGER NOT NULL DEFAULT 0,
  refreshed_at INTEGER NOT NULL
);
CREATE TABLE passkey (
  id TEXT PRIMARY KEY,               -- credential id, base64url
  public_key TEXT NOT NULL,          -- COSE public key, base64url
  counter INTEGER NOT NULL,
  transports TEXT,                   -- JSON array
  name TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  last_used_at INTEGER
);
CREATE TABLE auth_session (
  id TEXT PRIMARY KEY,               -- SHA-256 (hex) of the cookie token
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,       -- absolute: 24 hours after sign-in
  verified_at INTEGER NOT NULL,      -- last passkey check; linking banks and exports need one within 15 minutes
  passkey_id TEXT,
  user_agent TEXT
);
CREATE INDEX auth_session_expires ON auth_session (expires_at);
CREATE TABLE auth_challenge (
  id TEXT PRIMARY KEY,
  challenge TEXT NOT NULL,
  purpose TEXT NOT NULL CHECK (purpose IN ('register', 'login')),
  grant_kind TEXT,                   -- register only: 'setup' | 'device' | 'session'
  grant_ref TEXT,                    -- device link hash or session id
  expires_at INTEGER NOT NULL
);
CREATE TABLE device_link (
  token_hash TEXT PRIMARY KEY,
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  used_at INTEGER
);
